          "name": "gen_ai.invoke_agent.duration",
          "attributes": [
            "instrument=Histogram",
            "unit=s",
            "gen_ai.agent.name=SmashBot",
            "error.type on failure"
          ],
          "product_view": "Agent latency and failure filtering"
        }
      ],
      "follow_up_actions": [
        "After implementation inspect the received agent trace and duration measurements locally."
      ]
    }
